-- Module 2 (Machine Learning Fundamentals) content enrichment: adds visual
-- diagrams, in-lesson practice checks, worked code examples, and (lesson 8) an
-- interactive code_practice. Additive only (jsonb ||), existing hook/
-- explanation/analogy/fun_fact/try_it fields are untouched.
--
-- Lessons 8 and 12 are the flagship additions: a real, numerically-worked cost
-- function + gradient descent example (lesson 8) and a full six-step ML
-- pipeline that trains to convergence over 200 epochs (lesson 12) — matching
-- where DeepLearning.AI's own Machine Learning Specialization (Course 1, Week 1)
-- puts this exact material, instead of staying at narrative/analogy level.

UPDATE public.lesson_content lc
SET content = lc.content || '{"code":"# A tiny \"dataset\" — a list of examples, each with features + a label\ndataset = [\n    {\"size\": 1, \"bedrooms\": 1, \"price\": 12},\n    {\"size\": 2, \"bedrooms\": 1, \"price\": 20},\n    {\"size\": 3, \"bedrooms\": 2, \"price\": 28},\n    {\"size\": 4, \"bedrooms\": 2, \"price\": 35},\n]\n\n# Split: most examples for training, the rest held back to test honestly\ntrain_set = dataset[:3]\ntest_set  = dataset[3:]\n\nprint(f\"Training on {len(train_set)} examples, testing on {len(test_set)}\")","visual":{"caption":"Raw data becomes a trained model through a few concrete steps","steps":[{"emoji":"🗂️","label":"Raw Data","caption":"Numbers, text, images — collected from somewhere real."},{"emoji":"🧹","label":"Cleaning","caption":"Fixing errors, filling gaps, removing duplicates."},{"emoji":"🏷️","label":"Features & Labels","caption":"Splitting each example into \"the inputs\" and \"the correct answer\"."},{"emoji":"✂️","label":"Train/Test Split","caption":"Holding back some examples the model never gets to see while learning."},{"emoji":"✅","label":"Ready to Train","caption":"Clean, labeled, split — now it can actually be used."}]},"practice":{"prompt":"Why split data into a training set AND a separate test set, instead of training on everything?","options":["So you can honestly check whether the model generalizes, using examples it never saw while training","Because computers cannot process more than a few examples at once","To make the dataset file smaller","Test sets are only needed for images, not numbers or text"],"correct_index":0,"feedback":"A model that only gets graded on data it already memorized would always look perfect — the test set is what proves it actually learned the pattern, not just the answers."}}'::jsonb
FROM public.lessons l
WHERE l.id = lc.lesson_id AND l.order_index = 7;

UPDATE public.lesson_content lc
SET content = lc.content || '{"code":"# TRAINING = adjusting a guess until it fits the data\n# PREDICTING = using the finished model on new data\n\n# Toy example: predicting price from size (made-up units)\nsize = 3\nactual_price = 30\n\nweight = 2   # the model''s current guess at \"price per unit of size\"\nbias = 5\n\ndef predict(size, weight, bias):\n    return weight * size + bias\n\ndef cost(predicted, actual):\n    # squared error: how wrong the guess was, penalized more for being MORE wrong\n    return (predicted - actual) ** 2\n\nguess = predict(size, weight, bias)\nerror = cost(guess, actual_price)\nprint(f\"Guess: {guess}, Cost: {error}\")\n\n# GRADIENT DESCENT: nudge the weight in the direction that lowers cost\nlearning_rate = 0.01\ngradient = 2 * (guess - actual_price) * size   # the calculus, done for you\n\nweight = weight - learning_rate * gradient\n\nnew_guess = predict(size, weight, bias)\nnew_error = cost(new_guess, actual_price)\nprint(f\"After one training step -> Guess: {new_guess}, Cost: {new_error}\")","visual":{"caption":"The loop underneath every \"the model learned\" moment","steps":[{"emoji":"🎯","label":"Predict","caption":"Make a guess using the current weight and bias."},{"emoji":"📏","label":"Measure Error (Cost)","caption":"A single number: how wrong was that guess?"},{"emoji":"📐","label":"Compute the Gradient","caption":"Calculus tells you which direction reduces the error."},{"emoji":"🔧","label":"Adjust the Weight","caption":"Nudge it a little in that direction."},{"emoji":"🔁","label":"Repeat","caption":"Thousands of times, and the cost keeps dropping."}]},"practice":{"prompt":"In the code above, the cost dropped from 361 to about 243 after ONE training step. What does a smaller cost value actually mean?","options":["The model''s guess is getting closer to the real answer","The model is making a completely random guess","The model has stopped learning","The training data was deleted"],"correct_index":0,"feedback":"Cost is just a number that measures wrongness. Training is nothing more than repeatedly nudging the weights to make that number smaller."},"code_practice":{"instructions":"Finish the gradient descent step. Replace the placeholder line `weight = weight` with the real update rule: the new weight equals the old weight minus (learning_rate times gradient). This one line is the entire ''learning'' in machine learning.","starter":"size = 3\nactual_price = 30\n\nweight = 2\nbias = 5\n\ndef predict(size, weight, bias):\n    return weight * size + bias\n\ndef cost(predicted, actual):\n    return (predicted - actual) ** 2\n\nguess = predict(size, weight, bias)\nerror = cost(guess, actual_price)\nprint(f\"Guess: {guess}, Cost: {error}\")\n\nlearning_rate = 0.01\ngradient = 2 * (guess - actual_price) * size\n\n# TODO: replace this line with the gradient descent update rule\nweight = weight\n\nnew_guess = predict(size, weight, bias)\nnew_error = cost(new_guess, actual_price)\nprint(f\"After one training step -> Guess: {new_guess}, Cost: {new_error}\")","check_pattern":"weight\\s*=\\s*weight\\s*-\\s*\\(?\\s*learning_rate\\s*\\*\\s*gradient\\s*\\)?","success_message":"That''s it — that''s gradient descent. Every model, from this toy example to a real LLM, learns by repeating some version of that exact line, millions of times.","hint":"The pattern is: new_value = old_value - (learning_rate × gradient). Replace \"weight = weight\" with the full formula."}}'::jsonb
FROM public.lessons l
WHERE l.id = lc.lesson_id AND l.order_index = 8;

UPDATE public.lesson_content lc
SET content = lc.content || '{"code":"# Supervised learning: every example comes with the \"correct answer\" (label)\nlabeled_examples = [\n    (\"Win a free iPhone now!!!\", \"spam\"),\n    (\"Can we reschedule our meeting?\", \"not spam\"),\n    (\"You''ve won $1,000,000, claim now\", \"spam\"),\n    (\"Here''s the report you asked for\", \"not spam\"),\n]\n\nfor text, label in labeled_examples:\n    print(f\"''{text}'' -> {label}\")","visual":{"caption":"Learning from examples that already have the right answer attached","steps":[{"emoji":"🏷️","label":"Labeled Examples","caption":"Every input arrives with its correct answer already attached."},{"emoji":"🧠","label":"Model Studies Both","caption":"It sees the input AND the correct answer, together, many times."},{"emoji":"🔗","label":"Learns the Mapping","caption":"It figures out what pattern in the input predicts the label."},{"emoji":"❓","label":"New, Unlabeled Input","caption":"Now it''s shown something it''s never seen the answer for."},{"emoji":"✅","label":"Predicted Label","caption":"It applies the pattern it learned to guess the answer."}]},"practice":{"prompt":"Which of these is a supervised learning task?","options":["Training a model on emails that are each already marked \"spam\" or \"not spam\"","Handing a model a pile of customer purchase histories with no labels at all","Asking a model to group photos by visual similarity with no categories given","None of these involve a model at all"],"correct_index":0,"feedback":"Supervised learning specifically means every training example has a known, correct answer attached — that \"spam\"/\"not spam\" label is exactly that."}}'::jsonb
FROM public.lessons l
WHERE l.id = lc.lesson_id AND l.order_index = 9;

UPDATE public.lesson_content lc
SET content = lc.content || '{"visual":{"caption":"Finding structure when nobody tells you the \"correct\" groups","steps":[{"emoji":"📦","label":"Unlabeled Data","caption":"Just raw examples — no correct answers attached to any of them."},{"emoji":"🚫","label":"No Answer Key","caption":"Nobody tells the model what the ''right'' groups even are."},{"emoji":"🔎","label":"Look for Structure","caption":"The model measures how similar or different examples are to each other."},{"emoji":"🧩","label":"Group Similar Items","caption":"Examples that are alike get pulled into the same cluster."},{"emoji":"🌟","label":"Clusters Emerge","caption":"Patterns appear that a human never explicitly defined."}]},"practice":{"prompt":"A store has purchase histories for 10,000 customers with no predefined categories, and wants to discover natural shopper \"types\" on its own. What kind of learning is this?","options":["Unsupervised learning — finding structure with no labels given","Supervised learning, since customers are the labels","This is not something machine learning can do","Regression, since it involves numbers"],"correct_index":0,"feedback":"No correct answer exists to check against — the model has to discover the groupings itself from patterns in the data. That is unsupervised learning by definition."}}'::jsonb
FROM public.lessons l
WHERE l.id = lc.lesson_id AND l.order_index = 10;

UPDATE public.lesson_content lc
SET content = lc.content || '{"code":"# CLASSIFICATION: predicting a category (a limited set of labels)\ndef classify_email(is_spammy_words, many_links):\n    return \"spam\" if is_spammy_words and many_links else \"not spam\"\n\n# REGRESSION: predicting a number (any value on a continuous scale)\ndef predict_price(size_sqm):\n    return size_sqm * 1200 + 5000\n\nprint(classify_email(True, True))   # a category\nprint(predict_price(85))             # a number","visual":{"caption":"Same idea, two very different kinds of output","steps":[{"emoji":"🏷️","label":"Classification","caption":"Output is a category from a fixed set — spam/not spam, cat/dog/bird."},{"emoji":"📈","label":"Regression","caption":"Output is a number on a continuous scale — a price, a temperature."},{"emoji":"🤔","label":"Same Question","caption":"\"What kind of answer am I predicting?\" decides which one you need."}]},"practice":{"prompt":"A model predicts tomorrow''s temperature in degrees. Classification or regression?","options":["Regression — temperature is a number on a continuous scale","Classification — there are only a few possible temperatures","Neither — weather cannot be predicted by AI","Both, equally"],"correct_index":0,"feedback":"Any time the output is \"a number that could be almost anything\" rather than \"one of a few fixed categories,\" that is regression."}}'::jsonb
FROM public.lessons l
WHERE l.id = lc.lesson_id AND l.order_index = 11;

UPDATE public.lesson_content lc
SET content = lc.content || '{"code":"# A tiny end-to-end ML workflow, from raw data to a trained model\n\n# 1) COLLECT & 2) CLEAN: a small, already-cleaned dataset\nsizes  = [1, 2, 3, 4]      # feature: size\nprices = [12, 20, 28, 35]  # label: actual price\n\n# 3) SPLIT: hold back the last example to check the model honestly\ntrain_sizes, train_prices = sizes[:3], prices[:3]\ntest_size, test_price = sizes[3], prices[3]\n\n# 4) TRAIN: gradient descent over several passes (\"epochs\")\nweight, bias = 0.0, 0.0\nlearning_rate = 0.01\n\nfor epoch in range(200):\n    total_cost = 0\n    for x, y in zip(train_sizes, train_prices):\n        guess = weight * x + bias\n        error = guess - y\n        total_cost += error ** 2\n        weight -= learning_rate * 2 * error * x\n        bias   -= learning_rate * 2 * error\n    if epoch % 50 == 0:\n        print(f\"Epoch {epoch}: cost = {total_cost:.2f}\")\n\n# 5) EVALUATE: check against data the model never trained on\ntest_guess = weight * test_size + bias\nprint(f\"Test: predicted {test_guess:.1f}, actual {test_price}\")\n\n# 6) DEPLOY: use the trained weight/bias on brand-new input\nnew_size = 10\nprint(f\"Prediction for size={new_size}: {weight * new_size + bias:.1f}\")","visual":{"caption":"The same six steps behind every real ML project","steps":[{"emoji":"🗂️","label":"Collect","caption":"Gather real examples of the problem you want solved."},{"emoji":"🧹","label":"Clean","caption":"Fix errors, handle missing values, remove junk."},{"emoji":"✂️","label":"Split","caption":"Set aside test data the model will never train on."},{"emoji":"🏋️","label":"Train","caption":"Run gradient descent, over and over, until cost stops improving much."},{"emoji":"📊","label":"Evaluate","caption":"Check performance honestly, using the held-out test set."},{"emoji":"🚀","label":"Deploy","caption":"Use the trained model on brand-new, real-world input."}]},"practice":{"prompt":"In the code above, why does the printed cost keep getting smaller across epochs?","options":["Each epoch runs gradient descent again, nudging weight and bias a little closer to fitting the data","The dataset gets larger every epoch, which always lowers cost","The code is randomly guessing new numbers until one works","It is not actually getting smaller — the print statement is misleading"],"correct_index":0,"feedback":"Training IS repetition — the exact same weighted-update step from \"Training vs. Predicting\" happening again and again, each time getting a little more accurate."}}'::jsonb
FROM public.lessons l
WHERE l.id = lc.lesson_id AND l.order_index = 12;

UPDATE public.lesson_content lc
SET content = lc.content || '{"code":"# A tiny confusion matrix, tallied by hand\npredictions = [\"spam\", \"spam\", \"not spam\", \"spam\", \"not spam\"]\nactual      = [\"spam\", \"not spam\", \"not spam\", \"spam\", \"spam\"]\n\ntrue_positive  = sum(p == \"spam\" and a == \"spam\" for p, a in zip(predictions, actual))\nfalse_positive = sum(p == \"spam\" and a == \"not spam\" for p, a in zip(predictions, actual))\nfalse_negative = sum(p == \"not spam\" and a == \"spam\" for p, a in zip(predictions, actual))\n\nprecision = true_positive / (true_positive + false_positive)\nrecall    = true_positive / (true_positive + false_negative)\n\nprint(f\"Precision: {precision:.2f}, Recall: {recall:.2f}\")","visual":{"caption":"The four possible outcomes behind every prediction","steps":[{"emoji":"✅","label":"True Positive","caption":"Predicted positive, actually positive — a correct catch."},{"emoji":"❌","label":"False Positive","caption":"Predicted positive, actually negative — a false alarm."},{"emoji":"⚠️","label":"False Negative","caption":"Predicted negative, actually positive — a missed case."},{"emoji":"✔️","label":"True Negative","caption":"Predicted negative, actually negative — correctly ignored."}]},"practice":{"prompt":"A spam filter that marks NOTHING as spam, ever, technically has 0% recall on spam. What does that mean in practice?","options":["It lets every single real spam email straight through, undetected","It is extremely accurate and should be used as-is","Recall does not apply to spam filters","It means the filter has 100% precision, which is always good enough"],"correct_index":0,"feedback":"Zero recall means it catches none of the real positive cases — exactly like the \"always predict healthy\" model from earlier, technically \"accurate\" while being useless at the one job that mattered."}}'::jsonb
FROM public.lessons l
WHERE l.id = lc.lesson_id AND l.order_index = 13;

UPDATE public.lesson_content lc
SET content = lc.content || '{"visual":{"caption":"Five ways a model can quietly go wrong","steps":[{"emoji":"📌","label":"Overfitting","caption":"Memorized the training data, including its noise — fails on new examples."},{"emoji":"📉","label":"Underfitting","caption":"Too simple to capture the real pattern at all — wrong even on training data."},{"emoji":"⚖️","label":"Biased Data","caption":"The training set itself was skewed, so the model repeats that skew."},{"emoji":"🌍","label":"Distribution Shift","caption":"The real world changed since training — old patterns no longer hold."},{"emoji":"🎭","label":"Adversarial Input","caption":"Deliberately crafted input designed to trick the model."}]},"practice":{"prompt":"A model scores 99% on its training data but only 60% on brand-new examples. What is this called?","options":["Overfitting — it memorized the training set instead of learning the general pattern","Underfitting — it never learned anything at all","Perfect performance — 99% is a great score","Bias — the data must have been unfair to some group"],"correct_index":0,"feedback":"A huge gap between training and real-world performance is the textbook signature of overfitting — it got good at the exact examples it saw, not the underlying pattern."}}'::jsonb
FROM public.lessons l
WHERE l.id = lc.lesson_id AND l.order_index = 14;

